import tarfile,json,hashlib
from pathlib import Path
from statistics import mean
p=Path('/Users/pyeshuajs23/Downloads/amia-light-results.tar.gz');out=Path(__file__).resolve().parent
with tarfile.open(p) as t:data={m.name:json.load(t.extractfile(m)) for m in t.getmembers() if m.isfile() and m.name.endswith('.json')}
manifest=data.pop('manifest.json');results=[];signature=None

def check(rows,m):
 c={k:0 for k in ['tp','tn','fp','fn']}
 for r in rows:c['tp' if r['truth_member'] and r['pred_member'] else 'fn' if r['truth_member'] else 'fp' if r['pred_member'] else 'tn']+=1
 assert all(c[k]==m[k] for k in c)
 pos=[r['score'] for r in rows if r['truth_member']];neg=[r['score'] for r in rows if not r['truth_member']]
 auc=mean([float(a>b)+.5*(a==b) for a in pos for b in neg]);ba=(c['tp']/len(pos)+c['tn']/len(neg))/2
 assert abs(auc-m['roc_auc'])<1e-8 and abs(ba-m['adv'])<1e-8
 return {'counts':c,'balanced_accuracy':ba,'auc':auc}
for file,d in sorted(data.items()):
 if d['status']!='complete':continue
 rows=d['attack_trials'];check(rows,d['metrics'])
 s=[tuple(r[k] for k in ['trial_id','truth_member','target_index','target_sha256','target_seed','batch_pair_seed']) for r in rows]
 if signature is None:signature=s
 assert s==signature
 assert len(set(r['target_sha256'] for r in rows))==d['unique_target_count']==2
 for r in rows:assert r['pred_member']==(r['score']>=r['threshold'])
 pertarget={}
 for idx in sorted(set(r['target_index'] for r in rows)):
  rs=[r for r in rows if r['target_index']==idx];a=[r['score'] for r in rs if r['truth_member']];b=[r['score'] for r in rs if not r['truth_member']]
  pertarget[idx]={'correct':sum(r['pred_member']==r['truth_member'] for r in rs),'count':len(rs),'auc':mean([float(x>y)+.5*(x==y) for x in a for y in b])}
 es=[e for e in d['pipeline_evaluations'] if e.get('rag_conditions')];rag={}
 for n in es[0]['rag_conditions']:
  rs=[e['rag_conditions'][n] for e in es]
  for r in rs:
   check(r['membership_trials'],r['metrics'])
   for k,v in r['utility'].items():assert abs(mean(x[k] for x in r['utility_trials'])-v)<1e-8
  rag[n]={**{k:mean(r['metrics'][k] for r in rs) for k in ['adv','tpr','tnr']},**{k:mean(r['utility'][k] for r in rs) for k in ['token_f1','exact_match','answer_nll']},'recognition_rate':mean(r['diagnostics']['recognition_rate'] for r in rs)}
 results.append({'condition':d['pipeline']['condition'],'source':file,'metrics':d['metrics'],'per_target':pertarget,'rag':rag,'firestore_saved':d['firestore_saved'],'observation_privacy':d.get('observation_privacy_composed'),'training_privacy':d.get('training_privacy_composed'),'training_defense':d['pipeline']['defense']})
hours=(manifest['ended_unix']-manifest['started_unix'])/3600
summary={'archive_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'hours':hours,'excluded_noncomplete':len(data)-len(results),'runs':results}
(out/'summary.json').write_text(json.dumps(summary,indent=2))
lines=['# AMIA light pilot and comparison with Reference','',f'Nine completed experiments; no failed runs to exclude. Total elapsed time: {hours:.2f} hours. Each condition has 20 balanced batch observations across only two unique target records. The same target identities, seeds, batch-pair seeds and labels are used across conditions. All files report Firestore saving; remote persistence was not independently checked.','','Confusion counts, balanced accuracy, pooled score AUROC, threshold decisions and RAG utility averages were independently recomputed from saved rows. All checks passed. These checks establish internal consistency, not an independent rerun of the training process.','','## Attack results','','`adv` means balanced accuracy, not TPR minus FPR. Chance level is 50%.','','| Condition | Balanced accuracy | AUROC | TP / TN / FP / FN | Target 0 correct | Target 1 correct |','|---|---:|---:|---|---:|---:|']
for r in results:
 m=r['metrics'];lines.append(f"| {r['condition']} | {100*m['adv']:.0f}% | {m['roc_auc']:.2f} | {m['tp']} / {m['tn']} / {m['fp']} / {m['fn']} | {r['per_target'][0]['correct']}/10 | {r['per_target'][1]['correct']}/10 |")
lines+=['','## What the results establish','','**AMIA succeeds strongly in the tested setup.** Baseline detects all ten positive batches and falsely flags one of ten negative batches (95% balanced accuracy). Seven of nine settings retain 85–100% accuracy. These repeated batches cover two targets, so this is not evidence of success across twenty independent records.','','**Clipping alone does not suppress the attack.** Its accuracy remains 95% and AUROC remains 1.00. This is consistent with magnitude limiting leaving a detectable distinction between target-present and target-absent gradients. The result supports that explanation, rather than proving it universally.','','**Feature randomization leaves score separation intact.** BitRand reaches 85% and 90% calibrated accuracy; OME reaches 95%. All four have pooled AUROC 1.00. Thus the lower BitRand accuracy does not establish removal of the membership signal: at least on these saved scores, a threshold can separate positives and negatives perfectly. Selecting that threshold on test data would not be a valid estimate of deployment accuracy. Feature privacy is conditional on the next-token label; the archive explicitly disclaims full-text or training privacy from these mechanisms.','','**Gaussian noise on returned probe gradients weakens this attack.** Noise multipliers 1 and 2 both give 50% balanced accuracy, with AUROC 0.56 and 0.59. Sigma 1 gives one true positive and one false positive; sigma 2 predicts every batch negative. There is no evidence here that sigma 2 is decisively better. This concerns the observed probe-gradient release. It is not a demonstrated defense against every active strategy or repeated-query attack.','','**Training-only DP-SGD leaves AMIA successful.** At training noise multiplier 2, AMIA reaches 100% accuracy. Reference under training DP-SGD noise 2 previously reached 50%. This does not contradict a training guarantee: the saved AMIA methodology measures membership in a fresh private client batch through a malicious next-token head and its returned gradient. Reference measures membership in model training records through model scores. The observation channel remains separately exposed.','','## RAG utility and membership','','Means cover two evaluated fine-tuned models, with 200 membership candidates and 10 utility questions per corpus per model. These repeated questions must not be counted as independent samples across conditions.','','| Condition | Private ordinary RAG attack accuracy | Private ordinary answer F1 | Private exact match | Public ordinary answer F1 |','|---|---:|---:|---:|---:|']
for r in results:
 a=r['rag']['private_ordinary'];b=r['rag']['public_ordinary'];lines.append(f"| {r['condition']} | {100*a['adv']:.2f}% | {100*a['token_f1']:.2f}% | {100*a['exact_match']:.1f}% | {100*b['token_f1']:.2f}% |")
lines+=['','Gaussian observation noise preserves these measured answer scores: private ordinary answer F1 stays 47.86% and exact match stays 40%. Unlike the earlier Reference FedAvg results, the low attack score is not accompanied by collapse of measured RAG answer quality. However, the noise protects probe observations, not the generator training process, so these results do not measure the utility cost of adding equivalent noise to every ordinary FL update.','','Private ordinary RAG membership accuracy remains 57% under gradient-noise defenses, with TPR 50% and FPR 36%. Blocking AMIA has not demonstrated removal of retrieval membership leakage. The modest above-chance RAG result needs more independent models and questions before claiming reliable discrimination. Training-only DP-SGD yields private RAG attack accuracy 71% while answer F1 falls to 14.61%.','','Across the first eight conditions, classification and answer-quality averages coincide. These conditions share the same training mechanism; their interventions concern probe observations or frozen features. Repeated matching outcomes should not be presented as eight independent confirmations of RAG utility.','','For AMIA baseline private RAG, Mirabel reduces attack accuracy from 57% to 53%, but answer F1 falls from 47.86% to 18.92%. Instructions alone increase attack accuracy to 59.75% while answer F1 rises to 51.50%. Mirabel plus instructions gives 52.5% attack accuracy and 21.5% answer F1. The retrieval privacy/utility tradeoff remains.','','## Comparing the attack families','','| Property | AMIA pilot | Reference pilot |','|---|---|---|','| Membership question | Is the target in this private client batch? | Was the target used to train the model? |','| Observable | Returned gradient of malicious probe/head | Model score relative to reference model |','| Baseline balanced accuracy | 95% | 100% |','| Training DP-SGD sigma 2 | 100% | 50% |','| Unique target coverage per condition | 2 | 10 paired targets |','','Do not conclude that Reference is superior from 100% versus 95%: the membership questions, attacker access and independent target coverage differ. Both attacks succeed as pilot baselines. The contrast under training DP-SGD motivates separately protecting training outputs, client gradient observations and retrieval responses.','','## Formal privacy and reliability limits','','Gaussian observation accounting reports composed epsilon approximately 82.92 (sigma 1) and 31.46 (sigma 2), at delta 0.00001, over 20 private-batch gradient releases. These bounds exclude training, feature privacy and retrieval releases; they are not strong end-to-end privacy guarantees. Low measured attack accuracy is not equivalent to a small privacy bound.','','There is one sweep seed, one model/dataset setup, two unique AMIA targets and ten negative observations per condition. Test FPR resolution is 10 percentage points. Calibration on 200 negative batches does not add independent test outcomes. No general low-FPR reliability, broad attack ranking or universal defense effectiveness is established. Raw generated answer text is not present for qualitative auditing.','','## Study implication','','The most promising tested AMIA-specific intervention is protection of the returned probe gradients: it suppresses this attack while leaving measured RAG quality intact. The next validation should broaden independent target and seed coverage and test adaptive/repeated observations. An end-to-end defense still needs a separate treatment of retrieval leakage. Training DP alone should not be described as protecting every fresh client interaction.','',f"Source archive SHA-256: `{summary['archive_sha256']}`"]
(out/'analysis.md').write_text('\n'.join(lines)+'\n')
print('All recomputation checks passed. Hours:',hours)
for r in results:print(r['condition'],r['per_target'])
